private HWND _activationMonitorSource;

private HWND ResolveActivationMonitorSource(SelectedItem selectedItem)
{
    return selectedItem is SelectedItemByWindowHandle byWindowHandle &&
           byWindowHandle.WindowHandle != HWND.Null
        ? byWindowHandle.WindowHandle
        : new HWND(this.GetWindowHandle());
}

private void Initialize(SelectedItem selectedItem)
{
    _activationMonitorSource = ResolveActivationMonitorSource(selectedItem);
    ViewModel.ScalingFactor = _activationMonitorSource.GetMonitorScale();
    ViewModel.Initialize(selectedItem);
    // existing null-item guard and hook setup follow
}

// In Toggle, retain the existing Initialize(selectedItem); Activate() ordering,
// because Initialize now has the target monitor context before it starts preview work.

private void FilePreviewer_PreviewSizeChanged(object sender, PreviewSizeChangedArgs e)
{
    HWND monitorSource = TitleBarControl.Pinned
        ? new HWND(this.GetWindowHandle())
        : _activationMonitorSource;

    Size monitorSize = monitorSource.GetMonitorSize();
    double monitorScale = monitorSource.GetMonitorScale();
    Size requestedSize = e.PreviewSize.MonitorSize ?? monitorSize;
    double contentScale = e.PreviewSize.UseEffectivePixels ? 1d : monitorScale;
    Size scaledRequestedSize = new(requestedSize.Width / contentScale, requestedSize.Height / contentScale);
    Size adjustedContentSize = scaledRequestedSize.Fit(
        GetMonitorMaxContentSize(monitorSize, monitorScale),
        GetMonitorMinContentSize(monitorScale));

    double desiredWindowWidth = adjustedContentSize.Width;
    double desiredWindowHeight = adjustedContentSize.Height + TitleBarControl.ActualHeight;
    if (!TitleBarControl.Pinned)
    {
        this.CenterOnMonitor(monitorSource, desiredWindowWidth, desiredWindowHeight);
    }

    this.Show();
    WindowHelpers.BringToForeground(this.GetWindowHandle());
}

var w = width.HasValue
    ? Math.Max(1, (int)Math.Round(width.Value * scalingFactor, MidpointRounding.AwayFromZero))
    : windowRect.right - windowRect.left;
var h = height.HasValue
    ? Math.Max(1, (int)Math.Round(height.Value * scalingFactor, MidpointRounding.AwayFromZero))
    : windowRect.bottom - windowRect.top;

private long _previewGeneration;

private async Task UpdatePreviewSizeAsync(CancellationToken cancellationToken)
{
    if (Previewer == null)
    {
        return;
    }

    long generation = _previewGeneration;
    PreviewSize previewSize = await Previewer.GetPreviewSizeAsync(cancellationToken);
    cancellationToken.ThrowIfCancellationRequested();
    if (generation == _previewGeneration)
    {
        PreviewSizeChanged?.Invoke(this, new PreviewSizeChangedArgs(previewSize));
    }
}

